# Generated by GitHub Copilot
def _resolve_or_create_release_for_issue(
    db: Session,
    project: Project,
    selected_version_id: str | None,
    selected_version_name: str | None,
    counts: dict[str, int],
) -> Release | None:
    """
    Resolve release by project/version or create one when needed.

    Logic:
    1. Prefer Jira version id as the lookup key into releases.version
    2. Fallback to Jira version name if id lookup does not match
    3. If still not found, create release using the best available version token
    4. If no version info at all, fall back to the latest existing release for the project
    4. After db.flush(), release_id is auto-generated and available
    """
    if not selected_version_id:
        # Fall back to the latest existing release for this project
        latest = (
            db.query(Release)
            .filter(Release.project_id == project.project_id)
            .order_by(Release.release_id.desc())
            .first()
        )
        if latest:
            counts["releases_existing"] += 1
            return latest
        return None

    version_candidates: list[str] = []
    if selected_version_id:
        version_candidates.append(str(selected_version_id))
    if selected_version_name and selected_version_name not in version_candidates:
        version_candidates.append(selected_version_name)
    if not version_candidates:
        version_candidates.append("UNVERSIONED")

    existing_release = None
    for version_value in version_candidates:
        existing_release = (
            db.query(Release)
            .filter(
                Release.project_id == project.project_id,
                Release.version == version_value,
            )
            .first()
        )
        if existing_release:
            break

    if existing_release:
        # Release already exists - reuse it as-is.
        counts["releases_existing"] += 1
        return existing_release

    version_value = version_candidates[0]

    # Create new release with auto-generated release_id
    new_release = Release(
        project_id=project.project_id,
        release_name=project.project_name,
        version=version_value,
        status="In Progress",
        created_date=func.now(),
    )
    db.add(new_release)
    db.flush()  # Ensures release_id is auto-generated and available
    
    counts["releases_created"] += 1
    return new_release


# Generated by GitHub Copilot
def _upsert_work_item(
    db: Session,
    issue: dict,
    release: Release,
    counts: dict[str, int],
) -> None:
    """
    Insert or update one work item and map it to the resolved release.
    
    Ensures:
    - issue_key is the unique identifier
    - release_id is ALWAYS populated (never null) for Jira-synced items
    - Release MUST be provided (never None)
    - Updates existing items, inserts new ones
    - NEVER skips items
    """
    if not release:
        logger.warning(f"Cannot upsert work item {issue.get('key')} - no release provided")
        return
    
    issue_key = issue["key"]
    affects_ver = issue.get("selected_version") or None

    payload = {
        "title": issue["summary"],
        "status": issue["status"],
        "priority": issue["priority"] if issue.get("priority") else "Medium",
        "assigned_to": issue.get("assignee"),
        "issue_type": issue.get("issue_type"),
        "affects_version": affects_ver,
    }

    # If the issue has an Affects Version, try to find the matching release
    # by comparing against releases.version (normalised, strip leading 'v').
    resolved_release = release
    if affects_ver:
        norm_av = affects_ver.lstrip("vV").lower()
        all_releases = db.query(Release).all()
        for rel in all_releases:
            if rel.version and rel.version.lstrip("vV").lower() == norm_av:
                resolved_release = rel
                break

    try:
        # Check if work item already exists for this specific release
        work_item = db.query(WorkItem).filter(
            WorkItem.issue_key == issue_key,
            WorkItem.release_id == resolved_release.release_id,
        ).first()
        if not work_item:
            # Also check across all releases (avoid cross-release duplicates)
            work_item = db.query(WorkItem).filter(
                WorkItem.issue_key == issue_key,
            ).first()
        if work_item:
            for field, value in payload.items():
                setattr(work_item, field, value)
            work_item.release_id = resolved_release.release_id
            counts["work_items_updated"] += 1
            logger.debug(f"Updated work item {issue_key} -> release {resolved_release.release_id} (affects_version={affects_ver})")
            return

        # Create new work item
        new_item = WorkItem(
            issue_key=issue_key,
            release_id=resolved_release.release_id,
            title=payload["title"],
            status=payload["status"],
            priority=payload["priority"],
            assigned_to=payload["assigned_to"],
            issue_type=payload["issue_type"],
            affects_version=affects_ver,
        )
        db.add(new_item)
        counts["work_items_inserted"] += 1
        logger.debug(f"Inserted work item {issue_key} -> release {resolved_release.release_id} (affects_version={affects_ver})")
    except Exception as e:
        logger.error(f"Error upserting work item {issue_key}: {e}")
        raise


# Generated by GitHub Copilot
def _sync_workspace_projects_and_issues(db: Session) -> JiraWorkspaceSyncResponse:
    """
    Sync Jira workspace projects and issues into local project/release/work_item tables.
    
    Flow:
    1. Fetch all projects from Jira workspace
    2. For each project:
       a. Create or update local Project record
       b. Fetch all issues for that project
       c. For each issue:
          - Extract affected versions (affects/fix/versions)
          - Find or create Release by (project_id, version)
          - Create or update WorkItem linked to Release
    3. Commit all changes
    
    Ensures:
    - Releases are unique per (project_id, version)
    - All WorkItems have release_id populated
    - No duplicates are created
    """
    try:
        jira_projects = fetch_workspace_projects()
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Jira API error while listing projects: {exc}") from exc

    counts = {
        "projects_created": 0,
        "projects_existing": 0,
        "releases_created": 0,
        "releases_existing": 0,
        "work_items_inserted": 0,
        "work_items_updated": 0,
    }
    synced_keys: list[str] = []

    for jira_project in jira_projects:
        project_key = jira_project.get("key")
        project_name = jira_project.get("name") or project_key
        if not project_key:
            continue
        if is_excluded_project_name(project_name):
            continue

        # Find or create Project
        project = db.query(Project).filter(Project.jira_project == project_key).first()
        if project:
            if project.project_name != project_name:
                project.project_name = project_name
            counts["projects_existing"] += 1
        else:
            project = Project(project_name=project_name, jira_project=project_key)
            db.add(project)
            db.flush()  # Ensures project_id is available
            counts["projects_created"] += 1

        # Fetch issues for this project
        try:
            issues = fetch_project_issues(project_key)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=f"Jira API error while fetching issues for {project_key}: {exc}") from exc

        # Process each issue
        for issue in issues:
            # Resolve or create Release based on (project_id, version)
            release = _resolve_or_create_release_for_issue(
                db,
                project,
                issue.get("selected_version_id"),
                issue.get("selected_version"),
                counts,
            )
            
            # Upsert WorkItem mapped to Release
            _upsert_work_item(db, issue, release, counts)

        synced_keys.append(project_key)

    db.commit()

    return JiraWorkspaceSyncResponse(
        total_projects_from_jira=len(jira_projects),
        projects_created=counts["projects_created"],
        projects_existing=counts["projects_existing"],
        releases_created=counts["releases_created"],
        releases_existing=counts["releases_existing"],
        work_items_inserted=counts["work_items_inserted"],
        work_items_updated=counts["work_items_updated"],
        project_keys_synced=synced_keys,
    )


# Generated by GitHub Copilot
def _sync_project_issues_to_release(
    release_id: int,
    project_key: str,
    db: Session,
) -> JiraSyncResponse:
    """Sync Jira issues from one project key into a release's WorkItems.

    Only issues whose ``affectsVersion`` matches the release's ``version``
    are synced.  Issues with no affectsVersion set in JIRA are also included
    as a fallback so unversioned tickets are not lost.
    """
    release = db.query(Release).filter(Release.release_id == release_id).first()
    if not release:
        raise HTTPException(status_code=404, detail="Release not found")

    try:
        raw_issues = fetch_project_issues(project_key)
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Jira API error: {exc}") from exc

    # Filter issues to only those matching this release's version.
    release_version = (release.version or "").strip()
    if release_version and release_version.upper() != "UNVERSIONED":
        norm_rel_ver = release_version.lstrip("vV").lower()
        raw_issues = [
            issue for issue in raw_issues
            if issue.get("selected_version")
            and issue["selected_version"].lstrip("vV").lower() == norm_rel_ver
        ]

    existing_keys = {
        row.issue_key
        for row in db.query(WorkItem.issue_key)
        .filter(WorkItem.release_id == release_id)
        .all()
    }

    newly_synced = 0
    already_existed = 0
    response_issues: list[JiraIssue] = []

    for issue in raw_issues:
        affects_ver = issue.get("selected_version") or None
        jira_issue = JiraIssue(
            key=issue["key"],
            summary=issue["summary"],
            status=issue["status"],
            priority=issue["priority"],
            assignee=issue["assignee"],
            issue_type=issue["issue_type"],
            release_id=release_id,
            affects_version=affects_ver,
        )

        if issue["key"] in existing_keys:
            work_item = db.query(WorkItem).filter(
                WorkItem.issue_key == issue["key"],
                WorkItem.release_id == release_id,
            ).first()
            if work_item:
                work_item.title = issue["summary"]
                work_item.status = issue["status"]
                work_item.priority = issue["priority"] if issue["priority"] else "Medium"
                work_item.assigned_to = issue["assignee"]
                work_item.issue_type = issue["issue_type"]
                work_item.affects_version = affects_ver
            already_existed += 1
            response_issues.append(jira_issue)
            continue

        db.add(
            WorkItem(
                release_id=release_id,
                issue_key=issue["key"],
                title=issue["summary"],
                status=issue["status"],
                priority=issue["priority"] if issue["priority"] else "Medium",
                assigned_to=issue["assignee"],
                issue_type=issue["issue_type"],
                affects_version=affects_ver,
            )
        )
        newly_synced += 1
        existing_keys.add(issue["key"])
        response_issues.append(jira_issue)

    total_work_items = db.query(WorkItem).filter(WorkItem.release_id == release_id).count()
    release.total_work_items = total_work_items

    db.commit()

    return JiraSyncResponse(
        total_fetched=len(raw_issues),
        newly_synced=newly_synced,
        already_existed=already_existed,
        issues=response_issues,
    )


