@router.get("/releases/{release_id}/issues", response_model=list[JiraIssue])
def list_synced_jira_issues(release_id: int, db: Session = Depends(get_db)):
    """List Jira-synced WorkItems for a release."""
    items = db.query(WorkItem).filter(WorkItem.release_id == release_id).all()
    return [
        JiraIssue(
            key=item.issue_key,
            summary=item.title,
            status=item.status,
            priority=item.priority,
            assignee=item.assigned_to,
            issue_type=item.issue_type,
            release_id=item.release_id,
        )
        for item in items
    ]


@router.post("/releases/{release_id}/sync-from-project", response_model=JiraSyncResponse)
def sync_from_linked_project(release_id: int, db: Session = Depends(get_db)):
    """Sync Jira issues using the jira_project key configured on the release project."""
    release = (
        db.query(Release)
        .join(Project, Release.project_id == Project.project_id)
        .filter(Release.release_id == release_id)
        .first()
    )

    if not release:
        raise HTTPException(status_code=404, detail="Release not found")

    if not release.project or not release.project.jira_project:
        raise HTTPException(
            status_code=400,
            detail="No Jira project key set on this release's project. Set jira_project on the project first.",
        )

    return _sync_project_issues_to_release(release_id, release.project.jira_project, db)


@router.post("/workspace/sync", response_model=JiraWorkspaceSyncResponse)
def sync_workspace(db: Session = Depends(get_db)):
    """Sync all Jira workspace projects and related issues into local DB tables."""
    return _sync_workspace_projects_and_issues(db)


