@router.post("/recalculate-counts")
def recalculate_all_counts(db: Session = Depends(get_db)):
    """
    Recalculate and update total_work_items count for all releases.
    
    This endpoint fixes discrepancies between Jira issue counts and database counts
    by recounting all work items per release and updating the totals.
    """
    try:
        # Get all releases
        releases = db.query(Release).all()
        
        updated_count = 0
        for release in releases:
            # Count work items for this release
            work_item_count = db.query(WorkItem).filter(
                WorkItem.release_id == release.release_id
            ).count()
            
            # Update release total
            if release.total_work_items != work_item_count:
                logger.info(
                    f"Updating Release {release.release_id}: "
                    f"total_work_items {release.total_work_items} → {work_item_count}"
                )
                release.total_work_items = work_item_count
                updated_count += 1
        
        db.commit()
        
        return {
            "total_releases": len(releases),
            "releases_updated": updated_count,
            "message": f"Successfully recalculated counts for {updated_count} releases",
        }
    except Exception as exc:
        logger.error(f"Error recalculating counts: {exc}")
        db.rollback()
        raise HTTPException(status_code=500, detail=f"Error recalculating counts: {exc}")


