@router.post(
    "/work-items/remap-by-affects-version",
    summary="Remap work items to releases by their JIRA Affects Version",
)
def remap_work_items_by_affects_version(
    project_key: str = "AFCI",
    db: Session = Depends(get_db),
):
    """Fetch live JIRA issues, read their ``Affects Version`` field, match it
    against ``core.releases.version``, and update ``release_id`` on every
    matching work item in ``core.work_items``.

    Matching is case-insensitive with optional leading 'v' stripped
    (e.g. JIRA "v1.0.0" matches release version "1.0.0" or "v1.0.0").

    Returns a per-version breakdown of rows updated.
    """
    try:
        issues = fetch_project_issues(project_key)
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"Jira API error: {exc}") from exc

    try:
        # Ensure affects_version column exists — add it if not present
        with engine.connect() as _conn:
            _driver = engine.url.get_backend_name()
            if _driver == "sqlite":
                _cols = [row[1] for row in _conn.execute(text("PRAGMA table_info(work_items)")).fetchall()]
                if "affects_version" not in _cols:
                    _conn.execute(text("ALTER TABLE work_items ADD COLUMN affects_version VARCHAR(100)"))
                    _conn.commit()
            else:
                _exists = _conn.execute(text("""
                    SELECT column_name FROM information_schema.columns
                    WHERE table_schema = 'core'
                      AND table_name   = 'work_items'
                      AND column_name  = 'affects_version'
                """)).fetchone()
                if not _exists:
                    _conn.execute(text("ALTER TABLE core.work_items ADD COLUMN affects_version VARCHAR(100)"))
                    _conn.commit()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Migration error: {exc}") from exc

    try:
        releases = db.query(Release).all()
        version_map: dict[str, Release] = {}
        for rel in releases:
            if rel.version and rel.version.upper() != "UNVERSIONED":
                version_map[rel.version.lstrip("vV").lower()] = rel

        summary: dict[str, dict] = {}
        total_updated = 0
        not_matched: list[str] = []

        for issue in issues:
            issue_key: str = issue["key"]
            affects_ver: str | None = issue.get("selected_version")

            # Process ALL rows for this issue_key, not just the first
            all_rows = db.query(WorkItem).filter(WorkItem.issue_key == issue_key).all()

            if not all_rows:
                not_matched.append(f"{issue_key} (not in DB)")
                continue

            if not affects_ver:
                not_matched.append(f"{issue_key} (no Affects Version in JIRA)")
                # Still stamp affects_version=None on all rows
                for row in all_rows:
                    try:
                        row.affects_version = None
                    except Exception:
                        pass
                continue

            norm = affects_ver.lstrip("vV").lower()
            target_release = version_map.get(norm)
            if not target_release:
                not_matched.append(f"{issue_key} (version '{affects_ver}' not found in releases)")
                continue

            ver_label = affects_ver
            if ver_label not in summary:
                summary[ver_label] = {
                    "affects_version": ver_label,
                    "release_id": target_release.release_id,
                    "release_name": target_release.release_name,
                    "work_items_updated": 0,
                }

            # Stamp affects_version on all existing rows
            for row in all_rows:
                try:
                    row.affects_version = affects_ver
                except Exception:
                    pass

            correct_rows = [r for r in all_rows if r.release_id == target_release.release_id]
            wrong_rows = [r for r in all_rows if r.release_id != target_release.release_id]

            if correct_rows:
                # A correct row already exists — delete all wrong-release rows
                for row in wrong_rows:
                    db.delete(row)
                    total_updated += 1
                    summary[ver_label]["work_items_updated"] += 1
            else:
                # Move the first wrong row to the target release, delete the rest
                keep = wrong_rows[0]
                keep.release_id = target_release.release_id
                total_updated += 1
                summary[ver_label]["work_items_updated"] += 1
                for row in wrong_rows[1:]:
                    db.delete(row)

        db.commit()

        return {
            "total_updated": total_updated,
            "breakdown": list(summary.values()),
            "not_matched": not_matched,
        }
    except HTTPException:
        raise
    except Exception as exc:
        db.rollback()
        raise HTTPException(status_code=500, detail=f"Remap error: {exc}") from exc

